<"'!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Rompe Ladrillos</title>
<style>
:root{color-scheme:dark;--ink:#eaf4ff;--muted:#9eb3cb;--cyan:#58e5ef;--pink:#ff6d9b}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 0%,#193557 0,#0b1729 48%,#070d18 100%);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;display:flex;justify-content:center;padding:26px 16px}.wrap{width:min(900px,100%)}header{text-align:center;margin-bottom:20px}h1{font-size:clamp(2rem,5vw,3.2rem);line-height:1.1;margin:0 0 7px;letter-spacing:.04em}header p{margin:0;color:var(--muted)}.hud{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin:20px 0 12px}.badge{background:#14253a;border:1px solid #294563;border-radius:999px;padding:7px 15px;min-width:112px;text-align:center;color:var(--muted)}.badge strong{color:var(--ink);margin-left:6px;font-variant-numeric:tabular-nums}.game-shell{position:relative;border:1px solid #365572;border-radius:16px;overflow:hidden;box-shadow:0 22px 65px #0008,0 0 35px #41dce522;background:#091423}canvas{display:block;width:100%;height:auto;aspect-ratio:800/500;touch-action:none}.overlay{position:absolute;inset:0;display:grid;place-items:center;padding:20px;background:#071221b8;backdrop-filter:blur(4px);text-align:center}.overlay.hidden{display:none}.card{max-width:410px}.card h2{font-size:2rem;margin:0 0 8px}.card p{color:#c2d3e6;margin:0 0 18px}button{border:0;border-radius:999px;padding:11px 25px;background:linear-gradient(110deg,#55e1ef,#7b9cff);color:#071423;font:700 1rem system-ui;cursor:pointer;box-shadow:0 5px 20px #58e5ef44}button:hover{filter:brightness(1.08);transform:translateY(-1px)}.help{text-align:center;color:var(--muted);font-size:.9rem;margin:14px 0 0}.help kbd{background:#17283d;border:1px solid #38506c;border-radius:4px;padding:1px 6px;color:#dcecff}footer{text-align:center;color:#7288a2;font-size:.8rem;margin-top:10px}
</style>
</head>
<body>
<main class="wrap">
<header><h1>ROMPE LADRILLOS</h1><p>Rebota, apunta y despeja la pantalla.</p></header>
<section class="hud" aria-label="Estado de la partida"><div class="badge">Puntos<strong id="score">0</strong></div><div class="badge">Vidas<strong id="lives">3</strong></div><div class="badge">Nivel<strong id="level">1 / 2</strong></div></section>
<div class="game-shell"><canvas id="game" width="800" height="500" aria-label="Juego de romper ladrillos"></canvas><div class="overlay" id="overlay"><div class="card"><h2 id="message">¿Listo para jugar?</h2><p id="detail">Rompe todos los ladrillos. ¡Tienes dos niveles y tres vidas!</p><button id="start">Empezar</button></div></div></div>
<p class="help">Mover: <kbd>←</kbd> <kbd>→</kbd> o <kbd>A</kbd> <kbd>D</kbd> · También puedes mover el ratón · Pausa: <kbd>Espacio</kbd></p><footer>Un rebote más. Siempre uno más.</footer>
</main>
<script>
(()=>{'"'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),overlay=document.querySelector('#overlay'),message=document.querySelector('#message'),detail=document.querySelector('#detail'),startBtn=document.querySelector('#start'),scoreEl=document.querySelector('#score'),livesEl=document.querySelector('#lives'),levelEl=document.querySelector('#level');
const W=canvas.width,H=canvas.height,keys={};let score=0,lives=3,level=1,running=false,paused=false,raf=0,mouseX=null,bricks=[],particles=[];
const paddle={w:112,h:13,x:(W-112)/2,y:H-37,speed:8};const ball={x:W/2,y:H-55,r:8,dx:4,dy:-4,speed:5};
const layouts=[{rows:5,cols:10,colors:['#ff6685','#ff9f5b','#ffd45e','#62e3b1','#5ebcff']},{rows:6,cols:10,colors:['#bc83ff','#ff6cae','#ff9d57','#ffe06a','#63e3d0','#59a9ff']}];
function makeBricks(){bricks=[];const layout=layouts[level-1],gap=8,bw=(W-80-(layout.cols-1)*gap)/layout.cols,bh=22,left=40,top=66;for(let r=0;r<layout.rows;r++)for(let c=0;c<layout.cols;c++){const tough=level===2&&((r+c)%5===0);bricks.push({x:left+c*(bw+gap),y:top+r*(bh+gap),w:bw,h:bh,hp:tough?2:1,maxHp:tough?2:1,color:layout.colors[r%layout.colors.length],alive:true})}}
function resetBall(){ball.x=W/2;ball.y=H-55;ball.dx=(Math.random()<.5?-1:1)*4;ball.dy=-4.3;ball.r=8}
function updateHud(){scoreEl.textContent=score;livesEl.textContent=lives;levelEl.textContent=level+' / 2'}
function showOverlay(title,body,button='Jugar'){message.textContent=title;detail.textContent=body;startBtn.textContent=button;overlay.classList.remove('hidden')}
function begin(){if(level>2){level=1;score=0;lives=3;makeBricks()}if("'!bricks.length)makeBricks();running=true;paused=false;overlay.classList.add('"'hidden');resetBall();updateHud();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function nextLife(){lives--;updateHud();if(lives<=0){running=false;showOverlay('Fin de la partida','Has conseguido '+score+' puntos. ¿Probamos otra vez?','Reintentar');return}resetBall()}
function winLevel(){if(level===1){level=2;makeBricks();resetBall();updateHud();showOverlay('¡Nivel 1 superado"'!'"','Los ladrillos del segundo nivel son más resistentes.','Continuar');running=false}else{running=false;level=3;updateHud();showOverlay('¡Victoria"'!'"','Has despejado los dos niveles con '+score+' puntos.','Jugar de nuevo')}}
function burst(x,y,color){for(let i=0;i<7;i++)particles.push({x,y,dx:(Math.random()-.5)*4,dy:(Math.random()-.5)*4,life:24,color})}
function update(){if(mouseX"'!==null)paddle.x=mouseX-paddle.w/2;else{if(keys.ArrowLeft||keys.a||keys.A)paddle.x-=paddle.speed;if(keys.ArrowRight||keys.d||keys.D)paddle.x+=paddle.speed}paddle.x=Math.max(8,Math.min(W-paddle.w-8,paddle.x));ball.x+=ball.dx;ball.y+=ball.dy;
if(ball.x<ball.r||ball.x>W-ball.r)ball.dx*=-1;if(ball.y<ball.r)ball.dy*=-1;
if(ball.dy>0&&ball.y+ball.r>=paddle.y&&ball.y-ball.r<paddle.y+paddle.h&&ball.x>=paddle.x&&ball.x<=paddle.x+paddle.w){const hit=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);ball.dy=-Math.abs(ball.dy);ball.dx=hit*5.2;ball.y=paddle.y-ball.r}
