for(const b of bricks){if(!b.alive)continue;if(ball.x+ball.r>b.x&&ball.x-ball.r<b.x+b.w&&ball.y+ball.r>b.y&&ball.y-ball.r<b.y+b.h){ball.dy*=-1;b.hp--;burst(ball.x,ball.y,b.color);if(b.hp<=0){b.alive=false;score+=level===1?10:15;updateHud()}else score+=3;break}}
if(bricks.every(b=>!b.alive))winLevel();particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.dx;p.y+=p.dy;p.life--}}
function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'"'#10243a');bg.addColorStop(1,'#091321');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
ctx.strokeStyle='#91c9ff10';ctx.lineWidth=1;for(let x=20;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=20;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
for(const b of bricks){if("'!b.alive)continue;ctx.shadowColor=b.color;ctx.shadowBlur=9;ctx.fillStyle=b.color;roundedRect(b.x,b.y,b.w,b.h,5);ctx.shadowBlur=0;ctx.fillStyle='"'#ffffff40';roundedRect(b.x+3,b.y+3,b.w-6,4,2);if(b.hp>1){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(b.x+b.w/2,b.y+b.h/2,3,0,Math.PI*2);ctx.fill()}}
ctx.shadowColor='#57e8ff';ctx.shadowBlur=18;ctx.fillStyle='#55e4ef';roundedRect(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.shadowBlur=0;
ctx.shadowColor='#fff';ctx.shadowBlur=18;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
for(const p of particles){ctx.globalAlpha=p.life/24;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1}
function loop(){if("'!running||paused)return;update();draw();raf=requestAnimationFrame(loop)}
startBtn.addEventListener('"'click',begin);canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouseX=(e.clientX-r.left)*W/r.width});canvas.addEventListener('mouseleave',()=>mouseX=null);canvas.addEventListener('touchmove',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();mouseX=(e.touches[0].clientX-r.left)*W/r.width},{passive:false});canvas.addEventListener('touchend',()=>mouseX=null);
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '&&running){paused="'!paused;if(paused)showOverlay('"'Pausa','Pulsa Espacio o continuar para reanudar.','Continuar');else{overlay.classList.add('hidden');raf=requestAnimationFrame(loop)}}});window.addEventListener('keyup',e=>keys[e.key]=false);
makeBricks();updateHud();draw();
})();
</script>
</body>
</html>
